            break;
        } else {
            x *= 2;
        }
    }
}

fn sum_of_digits(n: Int) -> Int {
    let mut sum = 0
    let mut nn = n
    while nn > 0 {
        sum = sum + nn % 10
        nn = nn / 10
    }
    sum
}

